import assert from 'node:assert/strict';
import { Session } from './src/session.js';

for (const refetchOnReconnect of [false, true, undefined]) {
  let calls = 0;
  const session = new Session({
    queryFn({ signal }) { calls++; assert.equal(signal.aborted, false); return 'stop'; },
    timers: { schedule() {} }
  }, { online: false });
  const h = session.subscribe('station', { networkMode: 'online', refetchOnReconnect });
  session.online(true); // queues a resume
  session.unsubscribe(h); // leaves before the queued initial invocation
  await Promise.resolve();
  assert.equal(calls, 0, `calls with refetchOnReconnect=${refetchOnReconnect}`);
}

let calls = 0;
const shared = new Session({ queryFn() { calls++; return 'stop'; }, timers: { schedule() {} } }, { online: false });
const first = shared.subscribe('station', { networkMode: 'online' });
const second = shared.subscribe('station', { networkMode: 'online' });
shared.unsubscribe(first);
shared.online(true);
await Promise.resolve();
assert.equal(calls, 1);
shared.unsubscribe(second);
